const money = (value: number) => `₹${new Intl.NumberFormat('en-IN').format(value)}`;
const formatDate = (value: string, locale: string) => new Date(`${value}T12:00:00`).toLocaleDateString(locale, { day:'numeric', month:'short', year:'numeric' });
const dateLabel = (value: string) => formatDate(value, 'en-IN');
const localToday = () => {
  const now = new Date();
  return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
};
const interpolate = (text: string, values: Record<string, string | number>) => text.replace(/\{(\w+)\}/g, (_, key: string) => String(values[key] ?? ''));

